function tabOfHash(){let h='';try{h=decodeURIComponent(location.hash.slice(1))}catch(e){}if(!h)return 'bMap';const l=h.toLowerCase();if(l==='guide')return 'bGuide';if(l==='group')return 'bGroup';
 const t=document.getElementById(h);return t&&t.closest('#guide')?'bGuide':t&&t.closest('#group')?'bGroup':'bMap'}
/* Back/Forward between tabs (audit fix 2): each user tab change pushes one entry; the tab keeps its own scroll (tabY) */
{const onPop=()=>{const id=tabOfHash(),cur=tabs.find(t=>t.getAttribute('aria-selected')==='true');if(!cur||cur.id!==id){show(id,false,'pop');let g=null;try{g=document.getElementById(decodeURIComponent(location.hash.slice(1)))}catch(e){}if(g&&id!=='bMap'&&g.closest('.inner')){openTo(g);setTimeout(()=>g.scrollIntoView({block:'start'}),50)}}};addEventListener('popstate',onPop);addEventListener('hashchange',onPop)}
