/* ---- render (read-only) ---- */
const SR=t=>el('span',{className:'sr-only',textContent:t});
const CHIP={'Not booked':['not-booked','Not booked'],'Booked':['booked','Booked'],'Requested':['pending','Pending'],'Confirmed':['booked','Booked'],'Paid':['booked','Booked · paid'],'Cancelled':['cancelled','Cancelled']};
