/* Where the money goes: stacked CSS bars per category (paid / deposit / booked / estimate), exact cents in an sr-only table */
const CATS=[['Stays (Airbnb/hotel TBD) · est.',r=>/stay|airbnb|hotel|trenker|rodes|\bhb\b/i.test(r.item)],['Huts',isHut],['Transport',r=>/van|bus|fuel|parking|toll|taxi|train/i.test(r.item)],['Lifts',r=>/lift|chair|gondola|seceda/i.test(r.item)],['Taxes',r=>/tax/i.test(r.item)]];
