const HB_S={'Not booked':['not-booked','To book'],'Booked':['booked','Booked'],'Requested':['pending','Pending'],'Confirmed':['booked','Booked'],'Paid':['booked','Booked · paid'],'Cancelled':['cancelled','Cancelled']};
